def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    objs = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        shape = [[grid[r][c] for c in range(c0, c1 + 1)]
                 for r in range(r0, r1 + 1)]
        objs.append((r0, c0, shape))

    row_spread = max(o[0] for o in objs) - min(o[0] for o in objs)
    col_spread = max(o[1] for o in objs) - min(o[1] for o in objs)

    if col_spread >= row_spread:
        objs.sort(key=lambda o: o[1])
        out_h = max(len(o[2]) for o in objs)
        out_w = sum(len(o[2][0]) for o in objs)
        out = [[0] * out_w for _ in range(out_h)]
        x = 0
        for _, _, shape in objs:
            for r in range(len(shape)):
                for c in range(len(shape[0])):
                    out[r][x + c] = shape[r][c]
            x += len(shape[0])
    else:
        objs.sort(key=lambda o: o[0])
        out_h = sum(len(o[2]) for o in objs)
        out_w = max(len(o[2][0]) for o in objs)
        out = [[0] * out_w for _ in range(out_h)]
        y = 0
        for _, _, shape in objs:
            for r in range(len(shape)):
                for c in range(len(shape[0])):
                    out[y + r][c] = shape[r][c]
            y += len(shape)
    return out
